query getVariants($ids: [ID!]!) {
  nodes(ids: $ids) {
    id
    ... on ProductVariant {
      id
      title
      availableForSale
      price {
        amount
        currencyCode
      }
      image {
        url
      }
      product {
        title
        handle
        variantsCount {
          count
          precision
        }
      }
    }
  }
}

query getProducts($ids: [ID!]!) @inContext(language: EN, country: VN) {
  nodes(ids: $ids) {
    ...on Product {
      id
      title
      handle
      availableForSale
      variants(first: 250) {
        nodes {
          id
          title
          image {
            url
          }
          availableForSale
          price {
            amount
            currencyCode
          }
          metafield(namespace: "mysbox", key: "box") {
            value
          }
        }
      }
    }
  }
}
